mapper.select:
SELECT t.id, t.part_code AS partCode, t.part_name AS partName, t.parent_id AS parentId, COALESCE(p.part_name, '顶级部位') AS parentName, t.sort_order AS sortOrder, t.status FROM his_basedata_body t LEFT JOIN his_basedata_body p ON t.parent_id = p.id
AND (t.part_code LIKE CONCAT('%', #{keyword}, '%') OR t.part_name LIKE CONCAT('%', #{keyword}, '%'))
AND t.parent_id = #{parentId}
AND t.status = #{status}
ORDER BY t.sort_order ASC
